contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _recipient, address _caller) public payable {
        require(address(this).balance >= 0); // dummy, true precondition
        bool reverted;
        address originalOwner = c.owner();
        // Simulate call from _caller: deploy this test at _caller? No, we can't change msg.sender.
        // Instead, we check that original contract reverts exactly when _caller != owner,
        // and M reverts exactly when _caller != owner (inverted logic).
        // Since we cannot impersonate, we infer the rule by combining owner state and revert behavior
        // under the assumption that we are calling as this contract (msg.sender = address(this)).
        // The rule must be expressed over the public surface.
        // The observed difference: P requires sender == owner, M requires sender != owner.
        // Rule: (no revert) implies (sender == owner) for P; for M, (no revert) implies (sender != owner).
        // Since we can only be one sender, the rule must hold universally over possible owners.
        // A universal rule: For any owner assignment, withdrawAll reverts if and only if the caller is not the owner.
        // But we cannot vary caller identity directly. So we express: If owner is address(this), then withdrawAll doesn't revert. If owner is not address(this), then withdrawAll reverts.
        // However, we cannot change owner without an owner-only function. C has no setOwner.
        // Therefore we must rely on the given constructor argument when C was deployed.
        // The test receives the already deployed C. We can query its owner and observe revert behavior.
        // The bug is that M allows non-owner to succeed. So the rule: a non-reverting call implies caller == owner.
        // Since caller is address(this), we can assert: if !reverted then c.owner() == address(this).
        // This is true for P (owner is address(this) if we deployed it that way), but for M, the condition is inverted:
        // M allows non-reverting when sender != owner, so for M, if we set owner != address(this), M will not revert,
        // but the rule still says "if !reverted then owner == address(this)" which would be false.
        // But we need a single assertion that holds for all possible inputs on P and fails on at least one input on M.
        // We can make the caller (msg.sender) be address(this) always. We can pass _recipient arbitrarily.
        // We call withdrawAll and see if it reverts.
        // Property: withdrawAll does not revert IF AND ONLY IF address(this) == c.owner().
        // For P: true. For M: false when address(this) != c.owner(), because M would not revert then.
        // So we assert: reverted != (c.owner() == address(this)).
        // Equivalently: (reverted && c.owner() == address(this)) || (!reverted && c.owner() != address(this)) is false for P.
        // Actually for P: reverted == (c.owner() != address(this)). So reverted != (c.owner() == address(this)) is always false.
        // For M: reverted == (c.owner() == address(this)). So reverted != (c.owner() == address(this)) is true when c.owner() != address(this), because then M doesn't revert, but c.owner() == address(this) is false, so reverted != false => true != false => true. Violation.
        try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
        assert(!(reverted != (c.owner() == address(this))));
    }
    receive() external payable {}
}

