pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amt) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        amt = bound(amt, 1, 100 ether);
        vm.deal(address(c), amt);
        uint256 balBefore = recipient.balance;
        c.withdrawAll(recipient);
        uint256 balAfter = recipient.balance;
        assertTrue(address(c).balance == 0 && balAfter == balBefore + amt);
    }
}

